css_insertion:
/* Interactive floor replaces, never duplicates, the existing static leaf art. */
body > .platform-leaf-layer.platform-piles-interactive::after{visibility:hidden}
body > .platform-leaf-layer.platform-piles-interactive > .platform-pile{visibility:hidden}
body > .platform-leaf-layer > .platform-pile-surface{position:absolute;bottom:0;left:0;width:100%;height:112px;overflow:hidden;pointer-events:none;user-select:none;shape-rendering:crispEdges}
@media(max-width:760px){body > .platform-leaf-layer > .platform-pile-surface{height:84px}}
